import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { createCommentAction } from "@/actions/comments/create-comment";
import { deleteCommentAction } from "@/actions/comments/delete-comment";
import { CommentComposer } from "@/components/domain/comment/comment-composer";
import { CommentThread } from "@/components/domain/comment/comment-thread";
import { IssueActivityPanel } from "@/components/domain/issue/issue-activity-panel";
import { IssueDetail } from "@/components/domain/issue/issue-detail";
import { can } from "@/lib/permissions";
import { findIssueByNumber } from "@/server/repositories/issue-repository";
import { listActivityForSubject } from "@/server/repositories/activity-repository";
import { findUserById } from "@/server/repositories/user-repository";
import { getThread } from "@/server/services/comment-service";
import { getIssue } from "@/server/services/issue-service";
import { listMembers } from "@/server/services/member-service";
import type { CommentId } from "@/types/common";
import type { User } from "@/types/member";
import { loadProjectContext } from "../../../../_lib/project-context";

type PageParams = {
  orgSlug: string;
  projectSlug: string;
  issueNumber: string;
};

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Issue",
};

const MEMBER_PICKER_LIMIT = 100;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug, projectSlug, issueNumber } = await props.params;
  await props.searchParams;

  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);

  const number = Number.parseInt(issueNumber, 10);
  if (!Number.isInteger(number) || number < 1) {
    notFound();
  }

  // The number is only unique within a project, so the lookup is scoped to both
  // the org and the project — never to the number alone.
  const found = await findIssueByNumber(org.id, project.id, number);
  if (found === null) {
    notFound();
  }

  const allowed = can(actor, "issue:read", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: found.id,
    authorId: found.authorId,
    assigneeId: found.assigneeId,
  });
  if (!allowed) {
    notFound();
  }

  const [issue, thread, members, activity, author, assignee] = await Promise.all([
    getIssue(actor, org.id, found.id),
    getThread(actor, org.id, found.id),
    listMembers(actor, { orgId: org.id, limit: MEMBER_PICKER_LIMIT }),
    listActivityForSubject(org.id, "issue", found.id),
    findUserById(found.authorId),
    found.assigneeId === null
      ? Promise.resolve<User | null>(null)
      : findUserById(found.assigneeId),
  ]);

  if (author === null) {
    notFound();
  }

  const actors: Record<string, User> = {};
  for (const member of members.items) {
    actors[member.userId] = member.user;
  }

  async function deleteComment(commentId: CommentId): Promise<void> {
    "use server";
    await deleteCommentAction({ orgId: org.id, commentId });
  }

  return (
    <div className="grid gap-10 lg:grid-cols-[minmax(0,1fr)_18rem]">
      <div className="space-y-10">
        <IssueDetail
          issue={issue}
          actor={actor}
          author={author}
          assignee={assignee}
        />

        <section className="space-y-6">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Comments
          </h2>

          <CommentThread nodes={thread} actor={actor} onDelete={deleteComment} />

          <CommentComposer
            orgId={org.id}
            issueId={found.id}
            members={members.items}
            onSubmit={createCommentAction}
          />
        </section>
      </div>

      <IssueActivityPanel events={activity} actors={actors} />
    </div>
  );
}
/**
 * Renders a react-email component to the `{ subject, html, text }` triple
 * `EmailService` sends.
 *
 * `EmailTemplate` is the closed vocabulary of templates; this module is the
 * only place that maps a name to a component and to a subject line, so
 * adding a template means touching exactly one switch in each direction.
 */
import { render } from "@react-email/components";
import { createElement, type ReactElement } from "react";
import { SITE_CONFIG } from "@/config/site";
import type {
  EmailTemplate,
  RenderedEmail,
} from "@/server/services/email-service";
import { DigestEmail, type DigestEmailProps } from "./digest-email";
import { InviteEmail, type InviteEmailProps } from "./invite-email";
import { InvoiceEmail, type InvoiceEmailProps } from "./invoice-email";
import { MentionEmail, type MentionEmailProps } from "./mention-email";
import { OverdueEmail, type OverdueEmailProps } from "./overdue-email";
import {
  PasswordResetEmail,
  type PasswordResetEmailProps,
} from "./password-reset-email";
import { WelcomeEmail, type WelcomeEmailProps } from "./welcome-email";

type Props = Readonly<Record<string, unknown>>;

/** Reads a string prop defensively — templates are fed loosely typed payloads. */
function str(props: Props, key: string, fallback = ""): string {
  const value = props[key];
  return typeof value === "string" && value !== "" ? value : fallback;
}

function count(props: Props, key: string): number {
  const value = props[key];
  return Array.isArray(value) ? value.length : 0;
}

function elementFor(template: EmailTemplate, props: Props): ReactElement {
  switch (template) {
    case "invite":
      return createElement(InviteEmail, props as unknown as InviteEmailProps);
    case "digest":
      return createElement(DigestEmail, props as unknown as DigestEmailProps);
    case "mention":
      return createElement(MentionEmail, props as unknown as MentionEmailProps);
    case "invoice":
      return createElement(InvoiceEmail, props as unknown as InvoiceEmailProps);
    case "welcome":
      return createElement(WelcomeEmail, props as unknown as WelcomeEmailProps);
    case "password-reset":
      return createElement(
        PasswordResetEmail,
        props as unknown as PasswordResetEmailProps,
      );
    case "overdue":
      return createElement(OverdueEmail, props as unknown as OverdueEmailProps);
  }
}

/** The subject line for a template, derived from the same props as the body. */
export function subjectFor(template: EmailTemplate, props: Props): string {
  switch (template) {
    case "invite":
      return `${str(props, "inviterName", "Someone")} invited you to ${str(
        props,
        "orgName",
        SITE_CONFIG.name,
      )}`;
    case "digest": {
      const total = count(props, "entries");
      return `Your ${str(props, "orgName", SITE_CONFIG.name)} digest — ${total} update${
        total === 1 ? "" : "s"
      }`;
    }
    case "mention":
      return `${str(props, "actorName", "Someone")} mentioned you on "${str(
        props,
        "issueTitle",
        "an issue",
      )}"`;
    case "invoice":
      return `Invoice ${str(props, "invoiceNumber", "")} for ${str(
        props,
        "orgName",
        SITE_CONFIG.name,
      )}`.replace(/\s+/g, " ");
    case "welcome":
      return `Welcome to ${SITE_CONFIG.name}`;
    case "password-reset":
      return `Reset your ${SITE_CONFIG.name} password`;
    case "overdue": {
      const total = count(props, "issues");
      return `${total} overdue issue${total === 1 ? "" : "s"} in ${SITE_CONFIG.name}`;
    }
  }
}

/** Renders both the HTML and the plain-text alternative in one pass. */
export async function renderTemplate(
  template: EmailTemplate,
  props: Props,
): Promise<RenderedEmail> {
  const element = elementFor(template, props);
  const [html, text] = await Promise.all([
    render(element),
    render(element, { plainText: true }),
  ]);

  return { subject: subjectFor(template, props), html, text };
}
